-- Remove obsolete capacity caveats after the owner confirmed 6–10 guests.
UPDATE content_profiles SET payload=json_set(payload,'$.details."zh-Hans"',replace(json_extract(payload,'$.details."zh-Hans"'),'房源人数标注尚有差异，住宿上限待确认。','可入住6–10人。')),revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='rosewood-inn' AND instr(json_extract(payload,'$.details."zh-Hans"'),'房源人数标注尚有差异，住宿上限待确认。')>0;
UPDATE content_profiles SET payload=json_set(payload,'$.details."zh-Hant"',replace(json_extract(payload,'$.details."zh-Hant"'),'房源人數標註尚有差異，住宿上限待確認。','可入住6–10人。')),revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='rosewood-inn' AND instr(json_extract(payload,'$.details."zh-Hant"'),'房源人數標註尚有差異，住宿上限待確認。')>0;
UPDATE content_profiles SET payload=json_set(payload,'$.details."ja"',replace(json_extract(payload,'$.details."ja"'),'宿泊定員の記載に相違があり、確認中です。','宿泊人数は6〜10名です。')),revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='rosewood-inn' AND instr(json_extract(payload,'$.details."ja"'),'宿泊定員の記載に相違があり、確認中です。')>0;
UPDATE content_profiles SET payload=json_set(payload,'$.details."en"',replace(json_extract(payload,'$.details."en"'),'Published capacity figures differ and are being checked.','Accommodation capacity is 6–10 guests.')),revision=revision+1,updated_at=strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id='rosewood-inn' AND instr(json_extract(payload,'$.details."en"'),'Published capacity figures differ and are being checked.')>0;
